import glob,gzip,collections
def rd(f):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    if b[:2] in (b'\xff\xfe',b'\xfe\xff'): return b.decode('utf-16')
    if b[:3]==b'\xef\xbb\xbf': b=b[3:]
    import re
    m=re.search(rb'# charset: *(\S+)',b[:500])
    return b.decode(m.group(1).decode() if m else 'utf-8')
# field count anomalies
for pat,d in (('west*',';'),('river*','\t'),('harbor*','|')):
    c=collections.Counter()
    for f in sorted(glob.glob(pat)):
        hdr=None
        for l in rd(f).split('\n'):
            if not l or l[0]=='#': continue
            n=len(l.split(d))
            if l.startswith(('id;','t\t','rec|')): hdr=n; continue
            if n!=hdr: c[(f,n,hdr)]+=1; 
            if n!=hdr and c[(f,n,hdr)]<3: print(f,repr(l))
    print(pat,c)
c=collections.Counter()
for f in sorted(glob.glob('south*')):
    for l in rd(f).split('\n'):
        c[(l[:1] if l[:1] in '#\x0c' else 'rec',len(l.rstrip('\r')))]+=1
        if l[:1]=='\x0c' or len(l) not in (0,41,42,43) and l[0]!='#': print(repr(l))
print(c)
